// Shadow-root stylesheet, mirrored from agent-flow.css for bundler-safe loading.
export const AGENT_FLOW_CSS = ":host {\n  --af-background: #181818;\n  --af-text: #e5e5e5;\n  --af-muted: #a0a0a0;\n  --af-secondary: #929292;\n  --af-border: #343434;\n  --af-hover: #232323;\n  --af-focus: #aaa;\n  --af-error: #d4a19a;\n  display: block;\n  min-width: 0;\n  color: var(--af-text);\n  font: 400 13px/1.6 -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  color-scheme: dark;\n  overflow-wrap: anywhere;\n  -webkit-font-smoothing: antialiased;\n}\n*, *::before, *::after { box-sizing: border-box; }\n[hidden] { display: none !important; }\np, figure { margin: 0; }\na { color: inherit; text-decoration: none; }\na[href]:hover { text-decoration: underline; text-underline-offset: 3px; }\nbutton { font: inherit; color: inherit; cursor: pointer; }\nbutton:disabled { cursor: default; }\nbutton, summary, a, pre { -webkit-tap-highlight-color: transparent; }\n:where(button, summary, a, pre):focus-visible { outline: 2px solid var(--af-focus); outline-offset: 3px; }\n.flow > * + * { margin-top: 14px; }\n.text { white-space: pre-wrap; line-height: 1.7; }\nsummary {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-height: 28px;\n  width: fit-content;\n  max-width: 100%;\n  padding: 2px 0;\n  color: var(--af-muted);\n  list-style: none;\n  cursor: pointer;\n  user-select: none;\n  border-radius: 3px;\n}\nsummary::-webkit-details-marker { display: none; }\nsummary::marker { content: \"\"; }\nsummary:hover { color: var(--af-text); }\nsummary[aria-disabled=\"true\"] { cursor: default; }\n.label { min-width: 0; }\n.meta { flex-shrink: 0; color: var(--af-secondary); font-size: 12px; font-variant-numeric: tabular-nums; }\n.meta:empty { display: none; }\n.chevron {\n  flex: 0 0 6px;\n  width: 6px;\n  height: 6px;\n  margin: 0 3px;\n  border-right: 1px solid currentColor;\n  border-bottom: 1px solid currentColor;\n  transform: rotate(-45deg);\n  transition: transform 120ms ease;\n}\ndetails[open] > summary > .chevron { transform: rotate(45deg) translateY(-2px); }\n.reasoning-body { padding-top: 10px; color: var(--af-muted); white-space: pre-wrap; line-height: 1.75; }\n.reasoning[data-live=\"true\"] > summary > .label {\n  background: linear-gradient(100deg, var(--af-muted) 30%, var(--af-text) 50%, var(--af-muted) 70%);\n  background-size: 200% 100%;\n  background-clip: text;\n  -webkit-background-clip: text;\n  color: transparent;\n  animation: af-thinking 2s linear infinite;\n}\n@keyframes af-thinking { from { background-position: 200% 0; } to { background-position: -200% 0; } }\n.group-body { display: grid; gap: 9px; padding-top: 8px; }\n.group > summary > .meta { margin-left: 4px; }\n.tool { border: 1px solid var(--af-border); border-radius: 11px; overflow: clip; }\n.tool > summary { width: 100%; min-height: 37px; padding: 7px 10px; gap: 7px; }\n.tool > summary:hover { background: var(--af-hover); }\n.tool .label { flex-shrink: 1; color: var(--af-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.tool .hint { min-width: 0; flex: 1; color: var(--af-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.tool .meta { margin-left: auto; }\n.tool-icon { flex-shrink: 0; color: var(--af-secondary); font: 12px/1.4 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }\n.tool-body { border-top: 1px solid var(--af-border); }\n.payload + .payload { border-top: 1px solid var(--af-border); }\n.payload-head { display: flex; align-items: center; justify-content: space-between; padding: 5px 10px 0; color: var(--af-secondary); font-size: 11px; }\npre {\n  margin: 0;\n  padding: 5px 10px 10px;\n  max-height: 240px;\n  overflow: auto;\n  overscroll-behavior: contain;\n  color: var(--af-muted);\n  font: 12px/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  scrollbar-width: thin;\n  scrollbar-color: var(--af-border) transparent;\n}\n.quiet-button { padding: 2px 3px; min-height: 24px; border: 0; border-radius: 3px; background: transparent; color: var(--af-muted); font-size: 11px; }\n.quiet-button:hover { color: var(--af-text); background: var(--af-hover); }\n.more { margin: 0 7px 6px; }\n.error pre, [data-state=\"output-error\"] .tool .meta, [data-error=\"true\"], .format-error { color: var(--af-error); }\n.format-error { padding-top: 6px; font-size: 12px; }\n.approval { padding: 9px 0 0; }\n.approval-reason { color: var(--af-muted); margin-bottom: 7px; }\n.approval-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; }\n.approval-note { color: var(--af-muted); font-size: 12px; }\n.action { min-height: 30px; padding: 3px 10px; border: 1px solid var(--af-border); border-radius: 6px; background: transparent; }\n.action:hover:not(:disabled) { background: var(--af-hover); }\n.action:disabled { color: var(--af-secondary); }\n.artifacts { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 10px; }\n.artifact { width: 180px; max-width: 100%; min-width: 0; }\n.asset-preview {\n  width: 100%; aspect-ratio: 4 / 3; padding: 0; display: grid; place-items: center;\n  border: 1px solid var(--af-border); border-radius: 8px; overflow: hidden;\n  background: var(--af-background); cursor: zoom-in;\n}\n.asset-preview > * { grid-area: 1 / 1; }\n.asset-preview[data-loaded=\"false\"] img { opacity: 0; }\n.asset-preview img { width: 100%; height: 100%; object-fit: contain; min-width: 0; min-height: 0; }\n.asset-fallback { color: var(--af-muted); font-size: 11px; padding: 12px; }\nfigcaption { display: flex; flex-wrap: wrap; align-items: baseline; gap: 3px 8px; padding-top: 5px; font-size: 11px; color: var(--af-muted); }\n.dimensions { color: var(--af-secondary); font-variant-numeric: tabular-nums; }\n.source { color: var(--af-muted); font-size: 12px; }\n.footer { margin-top: 12px; color: var(--af-muted); }\n/* Motion means a real, currently streaming state; not decorative progress. */\n.reasoning[data-live=\"true\"] > summary::before,\n.tool-event[data-live=\"true\"] > .tool > summary::before,\n.footer[data-live=\"true\"]::before {\n  content: \"\"; display: inline-block; flex: 0 0 9px; width: 9px; height: 9px;\n  border: 1px solid var(--af-border); border-top-color: var(--af-muted); border-radius: 50%;\n  animation: af-spin 900ms linear infinite;\n}\n.footer[data-live=\"true\"]::before { margin-right: 7px; }\n.image-dialog {\n  max-width: min(96vw, 1200px); max-height: 94dvh; margin: auto; padding: 12px;\n  border: 1px solid var(--af-border); border-radius: 10px;\n  color: var(--af-text); background: var(--af-background);\n}\n.image-dialog::backdrop { background: rgb(0 0 0 / .76); }\n.image-dialog > button { display: block; margin: 0 0 10px auto; }\n.image-dialog > img { display: block; max-width: 100%; max-height: 74dvh; object-fit: contain; margin: auto; }\n.image-dialog > p { font-size: 12px; color: var(--af-muted); padding-top: 8px; }\n.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }\n@keyframes af-spin { to { transform: rotate(360deg); } }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation: none !important; transition: none !important; }\n}\n@media (pointer: coarse) { summary, .tool > summary, .action { min-height: 44px; } .quiet-button { min-height: 32px; } }\n@media (max-width: 420px) { .tool .hint { display: none; } .tool .meta { max-width: 42%; white-space: normal; text-align: right; } .artifact { width: calc(50% - 5px); } }\n";
